// StepUpFinishJSONRequestBody defines body for StepUpFinish for application/json ContentType.
type StepUpFinishJSONRequestBody = CeremonyFinish

// ServerInterface represents all server handlers.
type ServerInterface interface {

	// (GET /agents)
	ListAgents(w http.ResponseWriter, r *http.Request)

	// (POST /agents)
	CreateAgent(w http.ResponseWriter, r *http.Request)
	// RotateAgentToken Revoke the current token and issue a new enroll command
	// (POST /agents/{id}/rotate)
	RotateAgentToken(w http.ResponseWriter, r *http.Request, id ID)

	// (POST /agents/{id}/status)
	SetAgentStatus(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /audit)
	ListAudit(w http.ResponseWriter, r *http.Request, params ListAuditParams)

	// (GET /dashboard)
	GetDashboard(w http.ResponseWriter, r *http.Request)

	// (GET /extensions/{id})
	GetExtension(w http.ResponseWriter, r *http.Request, id ID)

	// (POST /extensions/{id}/deny)
	DenyExtension(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /grants)
	ListGrants(w http.ResponseWriter, r *http.Request, params ListGrantsParams)

	// (GET /grants/{id})
	GetGrant(w http.ResponseWriter, r *http.Request, id ID)

	// (POST /grants/{id}/deny)
	DenyGrant(w http.ResponseWriter, r *http.Request, id ID)

	// (POST /grants/{id}/revoke)
	RevokeGrant(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /hosts)
	ListHosts(w http.ResponseWriter, r *http.Request)
	// CreateHost Add a host and scan its host key
	// (POST /hosts)
	CreateHost(w http.ResponseWriter, r *http.Request)

	// (GET /hosts/{name})
	GetHost(w http.ResponseWriter, r *http.Request, name HostName)

	// (PATCH /hosts/{name})
	UpdateHost(w http.ResponseWriter, r *http.Request, name HostName)
	// ScanHost Rescan the host key. A changed key must be accepted with step-up.
	// (POST /hosts/{name}/scan)
	ScanHost(w http.ResponseWriter, r *http.Request, name HostName)

	// (POST /login/begin)
	LoginBegin(w http.ResponseWriter, r *http.Request)

	// (POST /login/finish)
	LoginFinish(w http.ResponseWriter, r *http.Request)

	// (POST /logout)
	Logout(w http.ResponseWriter, r *http.Request)

	// (GET /passkeys)
	ListPasskeys(w http.ResponseWriter, r *http.Request)
	// PasskeyRegisterFinish Finish adding a passkey (after an add_passkey step-up)
	// (POST /passkeys/register/finish)
	PasskeyRegisterFinish(w http.ResponseWriter, r *http.Request)

	// (PATCH /passkeys/{id})
	RenamePasskey(w http.ResponseWriter, r *http.Request, id ID)

	// (GET /session)
	GetSession(w http.ResponseWriter, r *http.Request)

	// (GET /sessions)
	ListSessions(w http.ResponseWriter, r *http.Request)
	// RevokeAllSessions Sign out everywhere, including this session
	// (POST /sessions/revoke-all)
	RevokeAllSessions(w http.ResponseWriter, r *http.Request)
	// SetupBegin Start first-passkey registration with the one-time setup code
	// (POST /setup/begin)
	SetupBegin(w http.ResponseWriter, r *http.Request)

	// (POST /setup/finish)
	SetupFinish(w http.ResponseWriter, r *http.Request)
	// StepUpBegin Validate an action and get a one-time challenge bound to it
	// (POST /stepup/begin)
	StepUpBegin(w http.ResponseWriter, r *http.Request)
	// StepUpFinish Verify the tap and apply exactly the stored action
	// (POST /stepup/finish)
	StepUpFinish(w http.ResponseWriter, r *http.Request)
}

