// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/session", wrapper.GetSession)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/setup/begin", wrapper.SetupBegin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/setup/finish", wrapper.SetupFinish)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/login/begin", wrapper.LoginBegin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/login/finish", wrapper.LoginFinish)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/logout", wrapper.Logout)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/stepup/begin", wrapper.StepUpBegin)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/stepup/finish", wrapper.StepUpFinish)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/dashboard", wrapper.GetDashboard)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/grants", wrapper.ListGrants)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/grants/{id}", wrapper.GetGrant)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/grants/{id}/deny", wrapper.DenyGrant)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/grants/{id}/revoke", wrapper.RevokeGrant)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/extensions/{id}", wrapper.GetExtension)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/extensions/{id}/deny", wrapper.DenyExtension)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts", wrapper.ListHosts)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/hosts", wrapper.CreateHost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/hosts/{name}", wrapper.GetHost)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/hosts/{name}", wrapper.UpdateHost)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/hosts/{name}/scan", wrapper.ScanHost)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/agents", wrapper.ListAgents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents", wrapper.CreateAgent)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{id}/rotate", wrapper.RotateAgentToken)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/agents/{id}/status", wrapper.SetAgentStatus)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/audit", wrapper.ListAudit)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/passkeys", wrapper.ListPasskeys)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/passkeys/register/finish", wrapper.PasskeyRegisterFinish)
	m.HandleFunc(http.MethodPatch+" "+options.BaseURL+"/passkeys/{id}", wrapper.RenamePasskey)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/sessions", wrapper.ListSessions)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/sessions/revoke-all", wrapper.RevokeAllSessions)

	return m
}

