// StrictServerInterface represents all server handlers.
type StrictServerInterface interface {

	// (GET /agents)
	ListAgents(ctx context.Context, request ListAgentsRequestObject) (ListAgentsResponseObject, error)

	// (POST /agents)
	CreateAgent(ctx context.Context, request CreateAgentRequestObject) (CreateAgentResponseObject, error)
	// RotateAgentToken Revoke the current token and issue a new enroll command
	// (POST /agents/{id}/rotate)
	RotateAgentToken(ctx context.Context, request RotateAgentTokenRequestObject) (RotateAgentTokenResponseObject, error)

	// (POST /agents/{id}/status)
	SetAgentStatus(ctx context.Context, request SetAgentStatusRequestObject) (SetAgentStatusResponseObject, error)

	// (GET /audit)
	ListAudit(ctx context.Context, request ListAuditRequestObject) (ListAuditResponseObject, error)

	// (GET /dashboard)
	GetDashboard(ctx context.Context, request GetDashboardRequestObject) (GetDashboardResponseObject, error)

	// (GET /extensions/{id})
	GetExtension(ctx context.Context, request GetExtensionRequestObject) (GetExtensionResponseObject, error)

	// (POST /extensions/{id}/deny)
	DenyExtension(ctx context.Context, request DenyExtensionRequestObject) (DenyExtensionResponseObject, error)

	// (GET /grants)
	ListGrants(ctx context.Context, request ListGrantsRequestObject) (ListGrantsResponseObject, error)

	// (GET /grants/{id})
	GetGrant(ctx context.Context, request GetGrantRequestObject) (GetGrantResponseObject, error)

	// (POST /grants/{id}/deny)
	DenyGrant(ctx context.Context, request DenyGrantRequestObject) (DenyGrantResponseObject, error)

	// (POST /grants/{id}/revoke)
	RevokeGrant(ctx context.Context, request RevokeGrantRequestObject) (RevokeGrantResponseObject, error)

	// (GET /hosts)
	ListHosts(ctx context.Context, request ListHostsRequestObject) (ListHostsResponseObject, error)
	// CreateHost Add a host and scan its host key
	// (POST /hosts)
	CreateHost(ctx context.Context, request CreateHostRequestObject) (CreateHostResponseObject, error)

	// (GET /hosts/{name})
	GetHost(ctx context.Context, request GetHostRequestObject) (GetHostResponseObject, error)

	// (PATCH /hosts/{name})
	UpdateHost(ctx context.Context, request UpdateHostRequestObject) (UpdateHostResponseObject, error)
	// ScanHost Rescan the host key. A changed key must be accepted with step-up.
	// (POST /hosts/{name}/scan)
	ScanHost(ctx context.Context, request ScanHostRequestObject) (ScanHostResponseObject, error)

	// (POST /login/begin)
	LoginBegin(ctx context.Context, request LoginBeginRequestObject) (LoginBeginResponseObject, error)

	// (POST /login/finish)
	LoginFinish(ctx context.Context, request LoginFinishRequestObject) (LoginFinishResponseObject, error)

	// (POST /logout)
	Logout(ctx context.Context, request LogoutRequestObject) (LogoutResponseObject, error)

	// (GET /passkeys)
	ListPasskeys(ctx context.Context, request ListPasskeysRequestObject) (ListPasskeysResponseObject, error)
	// PasskeyRegisterFinish Finish adding a passkey (after an add_passkey step-up)
	// (POST /passkeys/register/finish)
	PasskeyRegisterFinish(ctx context.Context, request PasskeyRegisterFinishRequestObject) (PasskeyRegisterFinishResponseObject, error)

	// (PATCH /passkeys/{id})
	RenamePasskey(ctx context.Context, request RenamePasskeyRequestObject) (RenamePasskeyResponseObject, error)

	// (GET /session)
	GetSession(ctx context.Context, request GetSessionRequestObject) (GetSessionResponseObject, error)

	// (GET /sessions)
	ListSessions(ctx context.Context, request ListSessionsRequestObject) (ListSessionsResponseObject, error)
	// RevokeAllSessions Sign out everywhere, including this session
	// (POST /sessions/revoke-all)
	RevokeAllSessions(ctx context.Context, request RevokeAllSessionsRequestObject) (RevokeAllSessionsResponseObject, error)
	// SetupBegin Start first-passkey registration with the one-time setup code
	// (POST /setup/begin)
	SetupBegin(ctx context.Context, request SetupBeginRequestObject) (SetupBeginResponseObject, error)

	// (POST /setup/finish)
	SetupFinish(ctx context.Context, request SetupFinishRequestObject) (SetupFinishResponseObject, error)
	// StepUpBegin Validate an action and get a one-time challenge bound to it
	// (POST /stepup/begin)
	StepUpBegin(ctx context.Context, request StepUpBeginRequestObject) (StepUpBeginResponseObject, error)
	// StepUpFinish Verify the tap and apply exactly the stored action
	// (POST /stepup/finish)
	StepUpFinish(ctx context.Context, request StepUpFinishRequestObject) (StepUpFinishResponseObject, error)
}

type StrictHandlerFunc func(ctx context.Context, w http.ResponseWriter, r *http.Request, request any) (any, error)
type StrictMiddlewareFunc func(f StrictHandlerFunc, operationID string) StrictHandlerFunc

type StrictHTTPServerOptions struct {
	RequestErrorHandlerFunc  func(w http.ResponseWriter, r *http.Request, err error)
	ResponseErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

func NewStrictHandler(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc) ServerInterface {
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: StrictHTTPServerOptions{
		RequestErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		},
		ResponseErrorHandlerFunc: func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		},
	}}
}

func NewStrictHandlerWithOptions(ssi StrictServerInterface, middlewares []StrictMiddlewareFunc, options StrictHTTPServerOptions) ServerInterface {
	if options.RequestErrorHandlerFunc == nil {
		options.RequestErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}
	if options.ResponseErrorHandlerFunc == nil {
		options.ResponseErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusInternalServerError)
		}
	}
	return &strictHandler{ssi: ssi, middlewares: middlewares, options: options}
}

type strictHandler struct {
	ssi         StrictServerInterface
	middlewares []StrictMiddlewareFunc
	options     StrictHTTPServerOptions
}

// ListAgents operation middleware
func (sh *strictHandler) ListAgents(w http.ResponseWriter, r *http.Request) {
	var request ListAgentsRequestObject

	handler := func(ctx context.Context, w http.ResponseWriter, r *http.Request, request interface{}) (interface{}, error) {
		return sh.ssi.ListAgents(ctx, request.(ListAgentsRequestObject))
	}
	for _, middleware := range sh.middlewares {
		handler = middleware(handler, "ListAgents")
	}

	response, err := handler(r.Context(), w, r, request)

	if err != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, err)
	} else if validResponse, ok := response.(ListAgentsResponseObject); ok {
		if err := validResponse.VisitListAgentsResponse(w); err != nil {
			sh.options.ResponseErrorHandlerFunc(w, r, err)
		}
	} else if response != nil {
		sh.options.ResponseErrorHandlerFunc(w, r, fmt.Errorf("unexpected response type: %T", response))
	}
}

